<script setup>
import {computed,ref} from 'vue';
import Icon from './HelmLabIcon.vue';
import {packageDate} from './test-packages.mjs';
import {compareEnvironments,compareSessionCases,comparisonSummary,outcomeLabel} from './test-package-comparison.mjs';

const props=defineProps({session:{type:Object,required:true},baseline:Object,busy:Boolean});
defineEmits(['select-case']);
const showUnchanged=ref(false);
const baselineRecord=computed(()=>props.baseline||props.session.baseline);
const rows=computed(()=>compareSessionCases(baselineRecord.value,props.session));
const summary=computed(()=>comparisonSummary(rows.value));
const environmentRows=computed(()=>compareEnvironments(baselineRecord.value?.environment,props.session.environment));
const changedEnvironment=computed(()=>environmentRows.value.filter(row=>row.status==='changed'));
const missingEnvironment=computed(()=>environmentRows.value.filter(row=>row.status==='unknown'));
const visibleEnvironment=computed(()=>showUnchanged.value?environmentRows.value:environmentRows.value.filter(row=>row.status!=='same'));
const caseLabel=state=>({same:'Same case & steps',changed:'Case content changed',added:'No baseline case',missing:'Not in candidate'}[state]);
const sessionEvidence=record=>(record?.evidence||[]).filter(item=>!item.caseId).length;
const gaps=computed(()=>[
  summary.value.notRun&&`${summary.value.notRun} not run`,summary.value.blocked&&`${summary.value.blocked} blocked`,
  summary.value.skipped&&`${summary.value.skipped} skipped`,summary.value.changed&&`${summary.value.changed} changed`,
  summary.value.added&&`${summary.value.added} without a baseline`,summary.value.missing&&`${summary.value.missing} missing from candidate`,
].filter(Boolean));
</script>

<template>
  <section v-if="baselineRecord" class="package-comparison" aria-label="Baseline and candidate comparison">
    <header class="pc-heading"><span class="pc-emblem"><Icon name="branch"/></span><div><span class="pc-eyebrow">BASELINE → CANDIDATE</span><h4>What changed between attempts?</h4><p>Compare the preserved case results and the environments they ran against.</p></div></header>
    <div class="pc-checkpoints"><div><span class="pc-eyebrow">PRESERVED BASELINE</span><strong>{{baselineRecord.name}}</strong><span>Rancher {{baselineRecord.environment?.rancherVersion||'version not recorded'}}</span><small>{{packageDate(baselineRecord.finishedAt,true)}}</small></div><Icon name="arrow"/><div><span class="pc-eyebrow">{{session.status==='active'?'CANDIDATE IN PROGRESS':'PRESERVED CANDIDATE'}}</span><strong>{{session.name}}</strong><span>Rancher {{session.environment?.rancherVersion||'version not recorded'}}</span><small>{{packageDate(session.status==='active'?session.startedAt:session.finishedAt,true)}}</small></div></div>
    <div class="pc-summary"><span><strong>{{summary.same}}</strong> matching {{summary.same===1?'case':'cases'}}</span><span><strong>{{summary.outcomeChanges}}</strong> outcome {{summary.outcomeChanges===1?'change':'changes'}}</span><span><strong>{{changedEnvironment.length}}</strong> environment {{changedEnvironment.length===1?'change':'changes'}}</span></div>
    <div v-if="gaps.length" class="pc-gaps"><Icon name="signal"/><div><strong>Keep these gaps in view</strong><p>{{gaps.join(' · ')}}. These cases do not establish a complete before-and-after result.</p></div></div>
    <div class="pc-table-wrap" tabindex="0" role="region" aria-label="Case comparison results, scroll horizontally on smaller screens"><table><caption class="pc-sr-only">Each row matches a case by its stable identifier and checks whether its content is unchanged.</caption><thead><tr><th scope="col">Case</th><th scope="col">Baseline</th><th scope="col">Candidate</th><th scope="col">Comparison</th></tr></thead><tbody><tr v-for="row in rows" :key="row.id" :class="{'pc-changed-case':row.comparability!=='same'}"><th scope="row"><button v-if="row.candidateCase" type="button" :disabled="busy" @click="$emit('select-case',row.id)">{{row.title}}<Icon name="arrow"/></button><span v-else>{{row.title}}</span></th><td><span v-if="row.baselineOutcome" class="pc-outcome" :data-outcome="row.baselineOutcome">{{outcomeLabel(row.baselineOutcome)}}</span><span v-else class="pc-absent">Not included</span><small v-if="row.baselineCase">{{row.baselineEvidence.length}} evidence {{row.baselineEvidence.length===1?'record':'records'}}</small></td><td><span v-if="row.candidateOutcome" class="pc-outcome" :data-outcome="row.candidateOutcome">{{outcomeLabel(row.candidateOutcome)}}</span><span v-else class="pc-absent">Not included</span><small v-if="row.candidateCase">{{row.candidateEvidence.length}} evidence {{row.candidateEvidence.length===1?'record':'records'}}</small></td><td><span class="pc-comparability" :class="{'pc-warning':row.comparability!=='same'}"><Icon :name="row.comparability==='same'?'check':'signal'"/>{{caseLabel(row.comparability)}}</span><small v-if="row.changes.length">{{row.changes.join(' · ')}}</small></td></tr></tbody></table></div>
    <p class="pc-evidence-note">Evidence counts are scoped to each case. Session-wide evidence: {{sessionEvidence(baselineRecord)}} baseline · {{sessionEvidence(session)}} candidate. Baseline entries are preserved references; attachment files are inspected in their original session when available.</p>
    <details class="pc-environment"><summary><Icon name="server"/><span>Environment comparison</span><small>{{changedEnvironment.length}} changed<template v-if="missingEnvironment.length"> · {{missingEnvironment.length}} incomplete</template></small><Icon name="chevron"/></summary><div class="pc-environment-content"><div class="pc-environment-controls"><p>Recorded values only. Missing information stays unknown; timestamps and source labels are not configuration changes.</p><label><input v-model="showUnchanged" type="checkbox"/>Show unchanged</label></div><p v-if="!visibleEnvironment.length" class="pc-no-changes">All recorded environment values match.</p><div v-for="row in visibleEnvironment" :key="row.key" class="pc-environment-row"><div class="pc-environment-label"><strong>{{row.label}}</strong><span :class="{'pc-warning':row.status==='unknown'}">{{row.status==='unknown'?'Not fully recorded':row.status==='changed'?'Changed':'Unchanged'}}</span></div><div><small>BASELINE</small><pre>{{row.before||'Not recorded'}}</pre></div><div><small>CANDIDATE</small><pre>{{row.after||'Not recorded'}}</pre></div></div></div></details>
    <footer><Icon name="lock"/><p>The baseline was copied when this validation session began. Case identity and content are checked separately. Different outcomes do not, by themselves, prove that a version change caused the difference.</p></footer>
  </section>
</template>

<style scoped>
