ong{font-size:11px;font-weight:600}.pc-gaps p{font-size:10px;color:var(--runway-muted);line-height:1.85;margin:5px 0 0}.pc-table-wrap{width:100%;overflow:auto;scrollbar-gutter:stable}.package-comparison table{width:100%;border-collapse:collapse;min-width:630px;text-align:left}.package-comparison th,.package-comparison td{padding:15px 20px;vertical-align:top;border-top:1px solid var(--runway-border);font-size:11px;font-weight:400;line-height:1.8}.package-comparison th:first-child{padding-left:25px;min-width:175px}.package-comparison td:last-child{padding-right:25px}.package-comparison thead th{font-size:9px;text-transform:uppercase;letter-spacing:.09em;color:var(--runway-muted);background:var(--runway-card);padding-top:11px;padding-bottom:11px;font-weight:600}.package-comparison tbody th{width:35%;font-weight:550}.package-comparison tbody th>span{overflow-wrap:anywhere}.package-comparison table button{display:flex;align-items:flex-start;justify-content:space-between;gap:10px;width:100%;font:inherit;text-align:left;border:0;background:transparent;padding:0;color:var(--runway-accent);cursor:pointer;overflow-wrap:anywhere}.package-comparison table button:hover{text-decoration:underline}.package-comparison table button:disabled{cursor:default;opacity:.55}.package-comparison table button svg{width:13px;height:13px;margin-top:3px}.package-comparison td>small{display:block;font-size:9px;line-height:1.8;color:var(--runway-muted);margin-top:6px}.pc-outcome{display:inline-flex;border:1px solid var(--runway-border);border-radius:6px;padding:3px 7px;font-size:10px;font-weight:550;background:var(--runway-card);white-space:nowrap;color:var(--runway-muted)}.pc-outcome[data-outcome=passed]{color:var(--runway-accent)}.pc-outcome[data-outcome=failed]{color:var(--runway-error)}.pc-outcome[data-outcome=blocked]{color:var(--runway-gold)}.pc-absent{color:var(--runway-muted);font-size:10px}.pc-comparability{display:flex;align-items:flex-start;gap:6px;font-size:10px;line-height:1.8;color:var(--runway-muted)}.pc-comparability svg{width:12px;height:12px;margin-top:3px;color:var(--runway-accent)}.pc-warning,.pc-warning svg{color:var(--runway-gold)}.pc-evidence-note{font-size:9px;line-height:1.85;color:var(--runway-muted);margin:0;padding:14px 25px;border-top:1px solid var(--runway-border)}
.pc-environment{border-top:1px solid var(--runway-border)}.pc-environment summary{display:flex;align-items:center;gap:9px;padding:17px 25px;cursor:pointer;list-style:none;font-size:11px;font-weight:550}.pc-environment summary::-webkit-details-marker{display:none}.pc-environment summary>svg:first-child{color:var(--runway-accent)}.pc-environment summary>svg:last-child{margin-left:auto}.pc-environment[open] summary>svg:last-child{transform:rotate(180deg)}.pc-environment summary small{font-size:9px;color:var(--runway-muted);font-weight:400}.pc-environment-content{padding:0 25px 18px}.pc-environment-controls{display:flex;align-items:center;justify-content:space-between;gap:20px;margin:0 0 16px}.pc-environment-controls p{font-size:10px;line-height:1.8;color:var(--runway-muted);margin:0}.pc-environment-controls label{display:flex;align-items:center;gap:7px;flex-shrink:0;font-size:10px;cursor:pointer}.pc-environment-controls input{appearance:auto;accent-color:var(--runway-accent);width:15px;height:15px;margin:0}.pc-environment-row{display:grid;grid-template-columns:150px minmax(0,1fr) minmax(0,1fr);gap:15px;padding:15px 0;border-top:1px solid var(--runway-border)}.pc-environment-label{display:grid;gap:5px;align-content:start}.pc-environment-label strong{font-size:11px;line-height:1.8;font-weight:550;overflow-wrap:anywhere}.pc-environment-label>span{color:var(--runway-muted);font-size:9px;line-height:1.6}.pc-environment-label>span.pc-warning{color:var(--runway-gold)}.pc-environment-row>div{min-width:0}.pc-environment-row small{font-size:8px;letter-spacing:.08em;color:var(--runway-muted)}.pc-environment-row pre{margin:5px 0 0;font:10px/1.85 ui-monospace,monospace;white-space:pre-wrap;overflow-wrap:anywhere;max-height:200px;overflow:auto}.pc-no-changes{font-size:11px;color:var(--runway-muted);margin:0 0 6px}.package-comparison footer{display:flex;align-items:flex-start;gap:8px;padding:16px 25px;border-top:1px solid var(--runway-border)}.package-comparison footer>svg{width:13px;height:13px;margin-top:2px;color:var(--runway-muted)}.package-comparison footer p{font-size:9px;line-height:1.85;color:var(--runway-muted);margin:0}.pc-sr-only{position:absolute;width:1px;height:1px;padding:0;margin:-1px;overflow:hidden;clip:rect(0,0,0,0);white-space:nowrap;border:0}
@container comparison (max-width:680px){.pc-environment-row{grid-template-columns:1fr 1fr}.pc-environment-label{grid-column:1/-1;display:flex;align-items:center;gap:10px}.pc-environment-controls{flex-direction:column;align-items:flex-start;gap:10px}.pc-heading{padding:20px}.pc-heading h4{font-size:18px}.pc-checkpoints{margin:0 20px;padding:16px;gap:10px}.pc-summary{padding:17px 20px}.pc-gaps{margin:0 20px 17px}.pc-environment summary{padding:16px 20px}.pc-environment-content{padding:0 20px 16px}.pc-evidence-note{padding:13px 20px}.package-comparison footer{padding:16px 20px}}
@container comparison (max-width:430px){.pc-checkpoints{grid-template-columns:1fr}.pc-checkpoints>svg{transform:rotate(90deg);justify-self:start;margin-left:5px}.pc-environment-row{grid-template-columns:1fr}.pc-environment-label{grid-column:auto}.pc-environment summary{flex-wrap:wrap;gap:7px}.pc-environment summary small{order:1;width:100%;padding-left:25px}.pc-summary{gap:12px 20px}}
</style>
